// withCiBuildHardening.js
//
// Expo Config Plugin — makes the Android *release* build survive CI.
//
// Applied as a config plugin rather than as an edit to `android/` because that
// directory is gitignored and regenerated by `expo prebuild` on every CI run,
// so any change committed to the generated Gradle files would be discarded.
//
// Two mods:
//
//   1. Disable Android Lint for release builds. The release variant runs
//      `lintVitalRelease`, whose lint workers load the class metadata of every
//      module into the Gradle daemon and exhaust the template's default
//      Metaspace cap, failing the build with `OutOfMemoryError: Metaspace`.
//      Lint adds no value to a release artifact in CI. This app is especially
//      exposed because expo-build-properties enables both
//      `enableProguardInReleaseBuilds` and
//      `enableShrinkResourcesInReleaseBuilds` in app.json.
//
//   2. Raise the Gradle daemon heap. The React Native template ships
//      `-Xmx2048m -XX:MaxMetaspaceSize=512m`, which is not enough for an
//      R8/ProGuard release build of this dependency tree. Applies to local
//      prebuilds too, which is a benefit at RN 0.83, not a regression.

const {
  withAppBuildGradle,
  withGradleProperties,
  createRunOncePlugin,
} = require('@expo/config-plugins');

const LINT_BLOCK = `    lint {
        checkReleaseBuilds false
        abortOnError false
    }`;

const JVM_ARGS_KEY = 'org.gradle.jvmargs';
const JVM_ARGS_VALUE = '-Xmx6g -XX:MaxMetaspaceSize=2g -XX:+HeapDumpOnOutOfMemoryError';

const withDisableReleaseLint = (config) =>
  withAppBuildGradle(config, (modConfig) => {
    const gradle = modConfig.modResults.contents;

    if (gradle.includes('checkReleaseBuilds false')) {
      return modConfig;
    }

    // Insert the block immediately after the opening `android {` brace.
    modConfig.modResults.contents = gradle.replace(
      /^(\s*)android\s*\{/m,
      (match) => `${match}\n${LINT_BLOCK}`
    );

    if (modConfig.modResults.contents === gradle) {
      console.warn(
        '[withCiBuildHardening] could not locate the `android {` block in app/build.gradle — release lint left enabled'
      );
    }

    return modConfig;
  });

const withGradleHeap = (config) =>
  withGradleProperties(config, (modConfig) => {
    const existing = modConfig.modResults.find(
      (item) => item.type === 'property' && item.key === JVM_ARGS_KEY
    );

    if (existing) {
      existing.value = JVM_ARGS_VALUE;
    } else {
      modConfig.modResults.push({
        type: 'property',
        key: JVM_ARGS_KEY,
        value: JVM_ARGS_VALUE,
      });
    }

    return modConfig;
  });

const withCiBuildHardening = (config) => withGradleHeap(withDisableReleaseLint(config));

module.exports = createRunOncePlugin(withCiBuildHardening, 'withCiBuildHardening', '1.0.0');
